import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    static class MinStack {
        private final Deque<Integer> dados = new ArrayDeque<>();
        private final Deque<Integer> minimos = new ArrayDeque<>();

        void push(int x) {
            dados.push(x);
            minimos.push(minimos.isEmpty() ? x : Math.min(x, minimos.peek()));
        }

        void pop() {
            if (dados.isEmpty()) throw new IllegalStateException("pilha vazia");
            dados.pop();
            minimos.pop();
        }

        int top() {
            if (dados.isEmpty()) throw new IllegalStateException("pilha vazia");
            return dados.peek();
        }

        int getMin() {
            if (minimos.isEmpty()) throw new IllegalStateException("pilha vazia");
            return minimos.peek();
        }
    }
}

