import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void minimoAcompanhaPop() {
        var s = new Solution.MinStack();
        s.push(5); s.push(3); s.push(7);
        assertEquals(3, s.getMin());
        s.pop();
        assertEquals(3, s.getMin());
        s.pop();
        assertEquals(5, s.getMin());
    }

    @Test void duplicadosNaoQuebram() {
        var s = new Solution.MinStack();
        s.push(2); s.push(2); s.push(1);
        s.pop();
        assertEquals(2, s.getMin());
    }

    @Test void vaziaFalha() {
        assertThrows(IllegalStateException.class, () -> new Solution.MinStack().getMin());
    }
}
